PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id = 1), payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(id, course_id));
CREATE TABLE IF NOT EXISTS topic_dependencies (topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, prerequisite_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, PRIMARY KEY(topic_id, prerequisite_id), CHECK(topic_id <> prerequisite_id));
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(topic_id, course_id) REFERENCES topics(id, course_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS exercises (id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS learning_sessions (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(topic_id, course_id) REFERENCES topics(id, course_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS exercise_attempts (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(topic_id, course_id) REFERENCES topics(id, course_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS mistakes (attempt_id TEXT PRIMARY KEY REFERENCES exercise_attempts(id) ON DELETE CASCADE, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS flashcards (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, topic_id TEXT, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(id, course_id), FOREIGN KEY(topic_id, course_id) REFERENCES topics(id, course_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, card_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(card_id, course_id) REFERENCES flashcards(id, course_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_messages (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS library_notes (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX IF NOT EXISTS topics_course ON topics(course_id);
CREATE INDEX IF NOT EXISTS attempts_topic ON exercise_attempts(topic_id);
CREATE INDEX IF NOT EXISTS cards_course ON flashcards(course_id);
INSERT OR IGNORE INTO schema_migrations(version) VALUES (1);
